let keep_5 = { let q: &dyn Query = g; ((q.state().apnap().collect::<Vec<PlayerId>>()).into_iter().map(|p: PlayerId| q.state().zone(Zone::hand(p)).len() as i64).min().unwrap_or(0)).max(0) as u32 }; let mut cards_5: Vec<ObjectId> = Vec::new(); for player in { let q: &dyn Query = g; q.state().apnap().collect::<Vec<PlayerId>>() } { let hand = g.state().zone(Zone::hand(player)).to_vec(); let extra = (hand.len() as u32).saturating_sub(keep_5); cards_5.extend(cantrip_mechanics::choose_from_hand(g, player, asker.source, extra)?); } let discarded_5 = g.discard_together(&cards_5);
